"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, type ReactNode, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a prompt box. Pass `value` to control the draft, or `defaultValue` to let it hold its own. */
export type PromptBoxProps = Omit<ComponentPropsWithoutRef<"form">, "children" | "defaultValue" | "onSubmit"> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Receives the trimmed draft. The draft clears after it. During a run, the message steers that run. */
  onSend?: (message: string) => void;
  /** Cancel the request here. Keep the text that already arrived. */
  onStop?: () => void;
  /** True while an answer is being written. The field stays live for the whole run. */
  streaming?: boolean;
  /** The line above the field during a run. Name the real step, never an invented one. */
  status?: ReactNode;
  /** Shown beside the status once the person types during a run, so they know where the message goes. */
  steerHint?: ReactNode;
  /** Names the field for screen readers. */
  label?: string;
  placeholder?: string;
};

const EASE_OUT = [0.165, 0.84, 0.44, 1] as const;
const SWAP: Transition = { duration: 0.2, ease: EASE_OUT };
const REVEAL: Transition = { duration: 0.25, ease: EASE_OUT };
// A fade is not travel, so reduced motion keeps it.
const FADE: Transition = { duration: 0.15 };

function SendGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <path d="M8 2a1 1 0 0 1 .7.3l4 4a1 1 0 1 1-1.4 1.4L9 5.4V13a1 1 0 1 1-2 0V5.4L4.7 7.7a1 1 0 0 1-1.4-1.4l4-4A1 1 0 0 1 8 2Z" />
    </svg>
  );
}

function StopGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <rect x="4" y="4" width="8" height="8" rx="2" />
    </svg>
  );
}

const ROUND_BUTTON = cn(
  // The button is 32px; the pseudo-element grows the hit area to 44px.
  "relative grid size-8 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full outline-none",
  "before:absolute before:-inset-1.5",
  "motion-safe:transition motion-safe:duration-150 active:scale-95",
  "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card",
);

/**
 * The message field of a chat. It grows with the draft up to a limit, Enter
 * sends and Shift+Enter adds a line. While an answer is being written, a status
 * line shows above the field and the send button becomes a stop button. Typing
 * during the run brings Send back beside Stop, so a follow-up never has to wait.
 */
export function PromptBox({
  value,
  defaultValue = "",
  onValueChange,
  onSend,
  onStop,
  streaming = false,
  status = "Writing the answer",
  steerHint = "Your message goes to this answer",
  label = "Message",
  placeholder = "Ask a question",
  className,
  ...formProps
}: PromptBoxProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const draft = value ?? ownValue;
  const hasText = draft.trim().length > 0;
  const field = useRef<HTMLTextAreaElement>(null);
  const reduceMotion = useReducedMotion();
  // With an empty draft during a run, the one button stops the run.
  const stops = streaming && !hasText;
  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6, filter: "blur(4px)" };

  const change = (next: string) => {
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const send = () => {
    if (!hasText) return;
    onSend?.(draft.trim());
    change("");
    // The button under the pointer is about to mean Stop, so focus goes back
    // to the field, where the next thing the person types belongs.
    field.current?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    // Enter confirms a composed character in many languages; that Enter is not a send.
    if (event.key !== "Enter" || event.shiftKey || event.nativeEvent.isComposing) return;
    event.preventDefault();
    send();
  };

  return (
    <form
      {...formProps}
      onSubmit={(event) => {
        event.preventDefault();
        send();
      }}
      className={cn("flex w-full flex-col", className)}
    >
      <div role="status" className="text-xs text-muted-foreground">
        <AnimatePresence initial={false}>
          {streaming && (
            <motion.div
              key="status"
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
              animate={reduceMotion ? { opacity: 1 } : { opacity: 1, height: "auto" }}
              exit={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
              transition={reduceMotion ? FADE : REVEAL}
              className="overflow-hidden"
            >
              <p className="flex items-center gap-2 px-3 pb-2">
                <span aria-hidden="true" className="size-1.5 shrink-0 rounded-full bg-muted-foreground motion-safe:animate-pulse" />
                <span>{status}</span>
                {hasText && <span className="ml-auto text-right">{steerHint}</span>}
              </p>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
      <div
        className={cn(
          "flex items-end gap-2 rounded-3xl border border-border bg-card p-2 pl-4",
          // Only the field lights the whole box. Each button shows its own ring.
          "has-[textarea:focus-visible]:ring-2 has-[textarea:focus-visible]:ring-ring",
        )}
      >
        {/* The hidden copy of the draft sizes the cell, so the field grows with no measuring. */}
        {/* The copy and the field share one size, 1rem, or they would wrap at different words. */}
        {/* The negative margin lets the field fill the box, so the whole 48px height takes the tap. */}
        <div className="-my-2 grid min-w-0 flex-1 text-base leading-6">
          <div
            aria-hidden="true"
            className="invisible col-start-1 row-start-1 max-h-46 overflow-hidden py-3 wrap-break-word whitespace-pre-wrap"
          >
            {`${draft}​`}
          </div>
          <textarea
            ref={field}
            rows={1}
            aria-label={label}
            placeholder={placeholder}
            value={draft}
            onChange={(event) => change(event.target.value)}
            onKeyDown={handleKeyDown}
            className="col-start-1 row-start-1 size-full resize-none overflow-y-auto bg-transparent py-3 text-base leading-6 text-foreground outline-none placeholder:text-muted-foreground"
          />
        </div>
        {streaming && hasText && (
          <motion.button
            type="button"
            aria-label="Stop the answer"
            onClick={() => onStop?.()}
            initial={hidden}
            animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
            transition={reduceMotion ? FADE : SWAP}
            className={cn(ROUND_BUTTON, "border border-border bg-background text-foreground hover:bg-muted")}
          >
            <StopGlyph />
          </motion.button>
        )}
        <button
          type={stops ? "button" : "submit"}
          aria-label={stops ? "Stop the answer" : "Send message"}
          disabled={!stops && !hasText}
          onClick={stops ? () => onStop?.() : undefined}
          className={cn(
            ROUND_BUTTON,
            "bg-primary text-primary-foreground hover:bg-primary/90",
            "disabled:cursor-not-allowed disabled:bg-muted disabled:text-muted-foreground disabled:active:scale-100",
          )}
        >
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.span
              key={stops ? "stop" : "send"}
              initial={hidden}
              animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
              exit={hidden}
              transition={reduceMotion ? FADE : SWAP}
              className="flex"
            >
              {stops ? <StopGlyph /> : <SendGlyph />}
            </motion.span>
          </AnimatePresence>
        </button>
      </div>
    </form>
  );
}
